from taf.rfrl.common_resources.reporting_portal.bts_metadata import bts_metadata

from taf.rfrl.procedures.resources.python.connections import get_default_admin_connection_alias, open_admin_connection
from taf.rfrl.procedures.resources.python.vm import get_testline_name
from taf.rfrl.procedures.resources.python.logger import log_input_and_output, log_to_console


@log_input_and_output
def report_tl_configuration(report, mode, logs_path=None):
    """
    Adds testline configuration data to test report.

    :param report: determines whether to report testline configuration (True) or skip the entire process (False)
    :type report: bool
    :param mode: specifies which BTS should be included in the report;
                 one of the following:
                     * gNB - configuration of only gNB will be reported
                     * eNB - configuration of only remote eNB will be reported
                     * gNB+eNB - configuration of both gNB and remote eNB will be reported
                     * eNB_SA - configuration of eNB in SA mode (LTE only, without gNB) will be reported
    :type mode: str
    :param logs_path: path to the directory where admin API logs will be stored;
                      defaults to None (default admin logs path will be used)
    :type logs_path: str
    """
    if report:
        log_to_console('Reporting testline configuration...')
        _validate_mode(mode)
        mode = mode.lower()
        bts_params = []

        if mode == 'gnb' or mode == 'gnb+enb':
            _add_bts_params(bts_params, logs_path, bts_type='GNB')

        if mode == 'enb' or mode == 'gnb+enb':
            _add_bts_params(bts_params, logs_path, bts_type='ENB', use_proxy=True, tl_name_suffix='_2')

        if mode == 'enb_sa':
            _add_bts_params(bts_params, logs_path, bts_type='ENB')

        bts_metadata().add_bts_metadata_to_report(bts_params=bts_params)
        log_to_console('Testline configuration was reported successfully')
    else:
        log_to_console('Testline configuration reporting was disabled by user')


def _validate_mode(mode):
    if mode.lower() not in ['gnb', 'enb', 'gnb+enb', 'enb_sa']:
        raise ValueError(f'Invalid reporting mode "{mode}" provided. Valid modes are: gNB, eNB, gNB+eNB, eNB_SA.')


def _add_bts_params(bts_params, logs_path, bts_type, use_proxy=False, tl_name_suffix=''):
    scout_tl_name = get_testline_name() + tl_name_suffix
    connection_alias = get_default_admin_connection_alias(bts_type=bts_type, use_proxy=use_proxy)
    open_admin_connection(alias=connection_alias, bts_type=bts_type, logs_path=logs_path)
    bts_params.append({'admin_connection': connection_alias,
                       'scout_bts_name': scout_tl_name})
